package {{clientPackageName}};

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/**
 * {{SCREEN_ID}} screen - generated by mcmodkit.
 * Size and texts come from the spec (ui.screens); edit the spec and regenerate instead of editing here.
 */
public class {{SCREEN_CLASS}} extends Screen {
	public static final int PANEL_WIDTH = {{SCREEN_WIDTH}};
	public static final int PANEL_HEIGHT = {{SCREEN_HEIGHT}};

	public {{SCREEN_CLASS}}() {
		super(Component.translatable("{{SCREEN_TITLE_KEY}}"));
	}

	@Override
	protected void init() {
		int left = (this.width - PANEL_WIDTH) / 2;
		int top = (this.height - PANEL_HEIGHT) / 2;
		this.addRenderableWidget(Button.builder(Component.translatable("gui.done"), button -> this.onClose())
			.bounds(left + PANEL_WIDTH / 2 - 50, top + PANEL_HEIGHT - 28, 100, 20)
			.build());
	}

	@Override
	public void render(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTick) {
		this.renderBackground(guiGraphics, mouseX, mouseY, partialTick);
		int left = (this.width - PANEL_WIDTH) / 2;
		int top = (this.height - PANEL_HEIGHT) / 2;
		guiGraphics.drawCenteredString(this.font, this.title, this.width / 2, top + 12, 0xFFFFFF);
{{SCREEN_LINE_DRAWS}}
		super.render(guiGraphics, mouseX, mouseY, partialTick);
	}

	@Override
	public boolean isPauseScreen() {
		return false;
	}
}

