templates.dataGenProvider:
package {{datagenPackageName}};

import java.nio.file.Path;
import java.util.concurrent.CompletableFuture;

import com.google.gson.JsonObject;

import net.minecraft.data.CachedOutput;
import net.minecraft.data.DataProvider;
import net.minecraft.data.PackOutput;

/**
 * Example data provider - generated by mcmodkit.
 *
 * It is the smallest useful provider: writing one JSON file into the mod's data pack when the data
 * run executes. Replace it with your own providers (recipes, models, tags, language, ...) or delete
 * it: the content mcmodkit generates from the spec already ships as plain JSON.
 */
public final class {{DATAGEN_PROVIDER_CLASS}} implements DataProvider {
	private final PackOutput output;

	public {{DATAGEN_PROVIDER_CLASS}}(PackOutput output) {
		this.output = output;
	}

	@Override
	public CompletableFuture<?> run(CachedOutput cache) {
		JsonObject json = new JsonObject();
		json.addProperty("generatedBy", "mcmodkit");
		json.addProperty("mod", "{{modId}}");
		Path path = this.output
			.getOutputFolder(PackOutput.Target.DATA_PACK)
			.resolve("{{namespace}}")
			.resolve("mcmodkit")
			.resolve("datagen.json");
		return DataProvider.saveStable(cache, json, path);
	}

	@Override
	public String getName() {
		return "{{modId}} example provider";
	}
}

