package {{datagenPackageName}};

import net.minecraft.data.DataGenerator;
import {{packageName}}.{{mainClassSimpleName}};
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.data.event.GatherDataEvent;

/**
 * Data generation entry point - generated by mcmodkit.
 * Run it with ./gradlew runData (output goes to src/generated/resources).
 */
@EventBusSubscriber(modid = {{mainClassSimpleName}}.MOD_ID, bus = EventBusSubscriber.Bus.MOD)
public final class {{DATAGEN_CLASS}} {
	@SubscribeEvent
	public static void gatherData(GatherDataEvent event) {
		DataGenerator generator = event.getGenerator();
		if (event.includeServer()) {
			generator.addProvider(true, new {{DATAGEN_PROVIDER_CLASS}}(generator.getPackOutput()));
		}
	}
}

